implementation.source:
void splatGeometry(
    mat4x4 viewProjection,
    mat4x4 world,
    vec2 viewportPixelSize,
    vec2 quadPosition[4],
    int primitiveID,
    vec3 cameraPosition,
    mat4x4 worldInverse,
    float shDegree,
    float shTexelsPerSplat,
    float fixedQuadSize,
    sampler2D shTextureSampler)
{
    GEO_OUT_struct outS = copyFromGEO_IN(0);

    // Per-splat frustum cull on the center (GL clip volume: -w <= z <= w).
    vec4 clip = viewProjection * vec4(outS.Pw, 1.0);
    if (clip.w <= 1.0e-6 || abs(clip.x) > clip.w || abs(clip.y) > clip.w
        || clip.z < -clip.w || clip.z > clip.w)
        return;

    // Rotation of the splat (identity when the quaternion is degenerate).
    vec4 q = outS.splatOrientation;
    float qLength = length(q);
    q = qLength > 1.0e-6 ? q / qLength : vec4(0.0, 0.0, 0.0, 1.0);
    float xx = q.x * q.x, yy = q.y * q.y, zz = q.z * q.z;
    float xy = q.x * q.y, xz = q.x * q.z, yz = q.y * q.z;
    float wx = q.w * q.x, wy = q.w * q.y, wz = q.w * q.z;
    mat3 rotation = mat3(
        1.0 - 2.0 * (yy + zz), 2.0 * (xy + wz), 2.0 * (xz - wy),
        2.0 * (xy - wz), 1.0 - 2.0 * (xx + zz), 2.0 * (yz + wx),
        2.0 * (xz + wy), 2.0 * (yz - wx), 1.0 - 2.0 * (xx + yy));

    // Ellipsoid axes in world space: columns are the semi-axes.
    vec3 scale = outS.splatScaleOpacity.xyz;
    mat3 axes = mat3(world) * rotation;
    axes[0] *= scale.x;
    axes[1] *= scale.y;
    axes[2] *= scale.z;

    // Jacobian of the NDC position with respect to the world-space position.
    float invW = 1.0 / clip.w;
    vec3 dClipW = vec3(viewProjection[0][3], viewProjection[1][3], viewProjection[2][3]);
    vec3 jacobianX = vec3(viewProjection[0][0], viewProjection[1][0], viewProjection[2][0]) * invW
        - dClipW * (clip.x * invW * invW);
    vec3 jacobianY = vec3(viewProjection[0][1], viewProjection[1][1], viewProjection[2][1]) * invW
        - dClipW * (clip.y * invW * invW);
    vec3 rowX = jacobianX * axes;
    vec3 rowY = jacobianY * axes;

    // Covariance of the projected ellipse in NDC, with a 0.3 pixel low-pass so that tiny
    // splats keep a visible footprint.
    vec2 lowPass = 0.6 / viewportPixelSize;
    float covXX = dot(rowX, rowX) + lowPass.x * lowPass.x;
    float covXY = dot(rowX, rowY);
    float covYY = dot(rowY, rowY) + lowPass.y * lowPass.y;

    // Eigen decomposition: the half axes of the quad are the standard deviations.
    float mid = 0.5 * (covXX + covYY);
    float radius = sqrt(max(0.25 * (covXX - covYY) * (covXX - covYY) + covXY * covXY, 0.0));
    float lambda1 = mid + radius;
    float lambda2 = max(mid - radius, 0.0);
    // Both expressions are eigenvectors of lambda1, take the better conditioned one.
    vec2 directionA = vec2(lambda1 - covYY, covXY);
    vec2 directionB = vec2(covXY, lambda1 - covXX);
    vec2 direction1 = dot(directionA, directionA) >= dot(directionB, directionB) ? directionA : directionB;
    float directionLength = length(direction1);
    direction1 = directionLength > 1.0e-30 ? direction1 / directionLength : vec2(1.0, 0.0);
    vec2 direction2 = vec2(-direction1.y, direction1.x);
    float extent1 = sqrt(lambda1);
    float extent2 = sqrt(lambda2);

    // Color: the SH0 stream, or the SH evaluated for the direction from the camera to the splat in
    // the prim's local space.
    vec3 rgb = outS.splatColor.rgb;
    int degree = int(shDegree + 0.5);
    if (degree > 0)
    {
        int texelsPerSplat = int(shTexelsPerSplat + 0.5);
        ivec2 textureDims = textureSize(shTextureSampler, 0);
        float values[48];
        for (int k = 0; k < 48; ++k)
            values[k] = 0.0;
        for (int k = 0; k < 12; ++k)
        {
            if (k < texelsPerSplat)
            {
                int texel = primitiveID * texelsPerSplat + k;
                vec4 t = texelFetch(shTextureSampler, ivec2(texel % textureDims.x, texel / textureDims.x), 0);
                values[4 * k + 0] = t.x;
                values[4 * k + 1] = t.y;
                values[4 * k + 2] = t.z;
                values[4 * k + 3] = t.w;
            }
        }
        vec3 sh[16];
        for (int c = 0; c < 16; ++c)
            sh[c] = vec3(values[3 * c], values[3 * c + 1], values[3 * c + 2]);

        vec3 dir = mat3(worldInverse) * (outS.Pw - cameraPosition);
        float dirLength = length(dir);
        dir = dirLength > 1.0e-20 ? dir / dirLength : vec3(0.0, 0.0, 1.0);
        float x = dir.x, y = dir.y, z = dir.z;

        vec3 result = 0.28209479177387814 * sh[0];
        result += -0.4886025119029199 * y * sh[1] + 0.4886025119029199 * z * sh[2]
            - 0.4886025119029199 * x * sh[3];
        if (degree > 1)
        {
            float xx = x * x, yy = y * y, zz = z * z;
            float xy = x * y, yz = y * z, xz = x * z;
            result += 1.0925484305920792 * xy * sh[4] - 1.0925484305920792 * yz * sh[5]
                + 0.31539156525252005 * (2.0 * zz - xx - yy) * sh[6]
                - 1.0925484305920792 * xz * sh[7] + 0.5462742152960396 * (xx - yy) * sh[8];
            if (degree > 2)
            {
                result += -0.5900435899266435 * y * (3.0 * xx - yy) * sh[9]
                    + 2.890611442640554 * xy * z * sh[10]
                    - 0.4570457994644658 * y * (4.0 * zz - xx - yy) * sh[11]
                    + 0.3731763325901154 * z * (2.0 * zz - 3.0 * xx - 3.0 * yy) * sh[12]
                    - 0.4570457994644658 * x * (4.0 * zz - xx - yy) * sh[13]
                    + 1.445305721320277 * z * (xx - yy) * sh[14]
                    - 0.5900435899266435 * x * (xx - 3.0 * yy) * sh[15];
            }
        }
        rgb = clamp(result + 0.5, 0.0, 1.0);
    }

    for (int i = 0; i < 4; ++i)
    {
        vec2 corner = quadPosition[i] * 2.0;
        vec2 offsetNdc = direction1 * (corner.x * extent1) + direction2 * (corner.y * extent2);
        if (fixedQuadSize > 0.0)
            // Axis-aligned square of fixedQuadSize pixels, whatever the scale and rotation.
            offsetNdc = corner * (fixedQuadSize / viewportPixelSize);
        outS.Pc = vec4(clip.xy + offsetNdc * clip.w, clip.zw);
        outS.ColorFromGS = vec4(rgb, 1.0);
        outS.UVFromGS = vec3(corner, outS.splatScaleOpacity.w);
        EmitGeoStruct(outS);
    }
    EndPrimitive();
}
